"use strict";
import LogoProvider from "components/Logo/LogoProvider";
import { Lock } from "react-feather";
import { Flex, Text, useSporeColors } from "ui/src";
import { formatABXAmount, formatTimeUntilUnlock, formatVotingPower } from "utils/lockCalculations";
import IncreaseExtendMergeTransferReset from "./IncreaseExtendMergeTransferReset";
export default function SingleLock({ lock }) {
  const colors = useSporeColors();
  const rowData = [
    {
      label: "Lock Type",
      value: lock.permanent ? "Permanent" : lock.managed ? "Managed" : "Standard"
    },
    {
      label: "Locked Amount",
      value: `${formatABXAmount(lock.amount)} ABX`
    },
    {
      label: "Voting Power",
      value: `${formatVotingPower(lock.votingPower)} veABX`
    },
    {
      label: "Unlock Date",
      value: lock.permanent ? "Permanent Lock" : formatTimeUntilUnlock(lock.lockEnd)
    }
  ];
  return <Flex
    $platform-web={{ display: "grid", gridTemplateColumns: "9fr 4fr 4fr 5fr 5fr" }}
    $lg={{ gridTemplateColumns: "1fr", padding: "$spacing12" }}
    p={"$spacing18"}
    borderRadius={"$rounded12"}
    gap={"$gap8"}
    borderWidth={1}
    borderColor={"$surface3"}
    transition='background-color 0.2s ease'
    hoverStyle={{
      backgroundColor: "$surface1Hovered"
    }}
  >
      <Flex className="left" row gap={"$gap12"} $lg={{ mb: "$spacing12" }}>
        <Flex
    height={50}
    width={50}
    centered
    borderRadius={"$rounded12"}
    borderWidth={1}
    borderColor={"$surface3"}
    row
    style={{
      background: `linear-gradient(90deg, ${colors.surface2Hovered.variable} 0%, ${colors.surface2.variable} 40%, ${colors.surface2Hovered.variable} 60%, ${colors.slate.variable} 100%)`
    }}
  >
          <LogoProvider color={colors.accent1.val} size={24} />
        </Flex>

        <Flex flexDirection="column" justifyContent="center" gap={"$gap8"} flex={1}>
          <Flex row gap={"$gap12"} alignItems="center">
            <Text>Lock #{lock.id}</Text>
            <Flex>
              <Lock size={14} color={colors.accent1Hovered.val} />
            </Flex>
          </Flex>

          <IncreaseExtendMergeTransferReset lockId={lock.id} />
        </Flex>
      </Flex>

      {rowData.map((item) => <Flex
    key={item.label}
    className="rebase"
    flexDirection="column"
    gap={"$gap12"}
    justifyContent="center"
    alignItems="flex-end"
    $lg={{
      borderTopWidth: 1,
      borderColor: "$surface3",
      py: "$spacing12",
      flexDirection: "row",
      justifyContent: "space-between"
    }}
  >
          <Text variant="body3" color={"$neutral2"}>
            {item.label}
          </Text>
          <Text variant="body3">{item.value}</Text>
        </Flex>)}
    </Flex>;
}
